// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Ensure the target is not the contract itself to avoid self-call edge cases
        vm.assume(target != address(c));
        // Record initial depositsCount
        uint256 initialCount = c.depositsCount();
        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeCall(c.sendMoney, (target, value)));
        // Assert that if the call succeeded, depositsCount remained unchanged
        assertTrue(!success || c.depositsCount() == initialCount);
    }
}

